use std::fs
use std::strings

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn new() -> Tree {
        Tree { keys: [], lefts: [], rights: [], root: -1 }
    }

    fn insert(self, x: int) -> bool {
        if self.root == -1 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur: int = self.root
        loop {
            let k = self.keys[cur as usize]
            if x == k {
                return false
            }
            if x < k {
                let l = self.lefts[cur as usize]
                if l == -1 {
                    let id = self.keys.len() as int
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.lefts[cur as usize] = id
                    return true
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r == -1 {
                    let id = self.keys.len() as int
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.rights[cur as usize] = id
                    return true
                }
                cur = r
            }
        }
        true
    }

    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        false
    }

    fn set_child(self, parent: int, old: int, new: int) {
        if parent == -1 {
            self.root = new
        } else if self.lefts[parent as usize] == old {
            self.lefts[parent as usize] = new
        } else {
            self.rights[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent: int = -1
        let mut cur: int = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        if cur == -1 {
            return false
        }
        let l = self.lefts[cur as usize]
        let r = self.rights[cur as usize]
        if l != -1 && r != -1 {
            let mut sp: int = cur
            let mut s: int = r
            while self.lefts[s as usize] != -1 {
                sp = s
                s = self.lefts[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rights[s as usize]
            self.set_child(sp, s, sr)
        } else if l != -1 {
            self.set_child(parent, cur, l)
        } else {
            self.set_child(parent, cur, r)
        }
        true
    }

    fn collect(self, n: int, out: Vec<int>) {
        if n == -1 {
            return
        }
        self.collect(self.lefts[n as usize], out)
        out.push(self.keys[n as usize])
        self.collect(self.rights[n as usize], out)
    }

    fn h(self, n: int) -> int {
        if n == -1 {
            return 0
        }
        let a = self.h(self.lefts[n as usize])
        let b = self.h(self.rights[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree::new()
    for line in text.lines() {
        let parts: Vec<string> = strings::split_whitespace(line)
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<int> = []
            t.collect(t.root, out)
            if out.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut first = true
                for v in out {
                    if first {
                        s = "${v}"
                        first = false
                    } else {
                        s = "${s} ${v}"
                    }
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.h(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c: int = t.root
                if cmd == "min" {
                    while t.lefts[c as usize] != -1 { c = t.lefts[c as usize] }
                } else {
                    while t.rights[c as usize] != -1 { c = t.rights[c as usize] }
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

